from decimal import ROUND_HALF_UP


# Minor-unit exponents: USD is 1/100, JPY has no fractional unit at all,
# KWD is 1/1000.  Anything not listed here is not a supported currency.
MINOR_UNITS = {"USD": 2, "JPY": 0, "KWD": 3}
ROUNDING = ROUND_HALF_UP


def scale(currency):
    try:
        exponent = MINOR_UNITS[currency]
    except KeyError:
        raise ValueError(f"unknown currency: {currency!r}") from None
    return 10 ** exponent
